import{c as t,W as o,j as a,n as i}from"./chunks/framework.Bl84hko2.js";const m=JSON.parse('{"title":"A Vision for Workbench","description":"","frontmatter":{"title":"A Vision for Workbench","updated":"2026-08-25T00:00:00.000Z"},"headers":[],"relativePath":"VISION.md","filePath":"VISION.md"}'),n={name:"VISION.md"};function s(r,e,h,l,c,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="a-vision-for-workbench" tabindex="-1">A Vision for Workbench <a class="header-anchor" href="#a-vision-for-workbench" aria-label="Permalink to “A Vision for Workbench”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Workbench is the structure that keeps agentic development honest.</p><p>An agent that goes straight from a request to an implementation produces code nobody specified, tests that agree with whatever got written, and documentation reverse-engineered from the result. Everything corroborates everything else, and none of it is evidence.</p><p>Workbench breaks that loop by insisting the same intent be written down more than once, in forms that can disagree: a proposal that records what was meant, tests that encode it executably, guides that explain it in prose, code that implements it, and a preview that lets a human exercise it. Disagreement between those representations is the signal. The process exists to surface it before release rather than after.</p><p>It is for someone who works with a coding agent daily, on projects they will still be maintaining in a year, and who has noticed that the failure mode is not bad code — it is code nobody decided on. Workbench assumes a single human owner reviewing an agent&#39;s work, not a large team with an existing request-for-comments process, and it assumes that human intends to remain the authority over product intent while delegating implementation.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to “Goals”">​</a></h2><p><strong>Make intent explicit before implementation begins.</strong> The proposal exists so that what was meant is recoverable independently of the conversation that produced it.</p><p><strong>Keep several independent representations of that intent.</strong> Proposal, tests, guides, code, and preview each describe the same behavior differently, so that a defect in one is visible against the others.</p><p><strong>Make disagreement between them visible before release.</strong> Cross-artifact review and adversarial review exist to find contradictions, not to confirm that work looks finished.</p><p><strong>Preserve the reasoning, not just the result.</strong> Proposals, decisions, policies, and review discussion outlive the change. A future reader needs to know why, and the diff will not tell them.</p><p><strong>Keep the human as the final authority.</strong> Agents implement, review, and refute. They do not ratify their own work.</p><h2 id="minimum-viable-product" tabindex="-1">Minimum viable product <a class="header-anchor" href="#minimum-viable-product" aria-label="Permalink to “Minimum viable product”">​</a></h2><p>A repository you can clone that gives a project, on day one:</p><ul><li>the artifact structure — vision, policies, decisions, proposals, guides — with templates that make the right shape the easy shape;</li><li>skills covering each phase of the process, written so any competent coding agent can execute them;</li><li>a validator that mechanically enforces the parts of the process a machine can check, wired into continuous integration and a git hook;</li><li>a documentation site that publishes the vision, the record, and the guides;</li><li>a preview mechanism appropriate to what the project is.</li></ul><p>It must be adoptable by an agent in a single session, and it must not assume a language, a framework, a platform, or a particular coding harness.</p><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design principles”">​</a></h2><p><strong>No single artifact defines a feature.</strong> Every representation is a check on the others. Removing one does not simplify the process; it removes a check.</p><p><strong>Enforce mechanically or not at all.</strong> A rule that lives only in prose is a rule that will be missed. Anything expressible as a validator rule, a continuous-integration step, or a template section belongs there instead.</p><p><strong>Ceremony must earn its cost.</strong> Every step exists because skipping it produced a specific, recurring failure. A step that cannot be justified that way gets deleted.</p><p><strong>Templates teach.</strong> A template that only names its sections produces documents that only fill them in. Each one carries enough instruction that a good document can be written from it alone.</p><p><strong>Previews expose behavior, not descriptions of behavior.</strong> Review of prose is not review of behavior, so every change is exercised through the cheapest realistic artifact that runs.</p><h2 id="beyond-the-minimum" tabindex="-1">Beyond the minimum <a class="header-anchor" href="#beyond-the-minimum" aria-label="Permalink to “Beyond the minimum”">​</a></h2><p>Directions worth considering once the core is proven:</p><ul><li>richer mechanical checks — proposals with no corresponding tests, guides describing behavior no test covers, policies no proposal has cited in a long time;</li><li>a dependent-project workflow, where a preview published by one repository is consumed by draft pull requests in others and moved onto the production release automatically;</li><li>worked examples of the process running end to end on projects of different shapes, since the hardest thing to convey about a process is what good output looks like;</li><li>measurement of whether adversarial review catches what confirmatory review misses, and which stages earn their cost in practice.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><p><strong>Not a project scaffold.</strong> Workbench does not choose your language, framework, or architecture. Version 1 did, and the process became the small part of a large repository about stacks.</p><p><strong>Not tied to one coding harness.</strong> Infrastructure ships harness-neutral in <code>.agents/</code> because shipping configuration for harnesses nobody here verifies is worse than a documented adaptation step.</p><p><strong>Not an issue tracker.</strong> The proposal queue is the work queue, and defects that outlive a pull request go to the project&#39;s issue tracker. Tools that track work better than a directory of markdown files already exist, and competing with them would cost more than it returns.</p><p><strong>Not a substitute for judgement.</strong> Every gate here can be satisfied superficially by an agent determined to look done. The process makes that harder and more visible; it does not make it impossible, and treating it as though it does would be the most expensive mistake available.</p><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><ul><li><strong>2026-08-25</strong> — Initial vision, written alongside <a href="./proposals/0001-workbench-2">proposal.0001</a>.</li></ul>',32)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
